using System.Globalization;using MiniStore.Application.DTOs.Purchases;using MiniStore.Domain.Entities;using MiniStore.Domain.Interfaces;
namespace MiniStore.Application.Services;
public sealed class PurchaseTemplateService(IPurchaseTemplateRepository templates,IPurchaseOrderRepository orders,IPurchaseRequestRepository requests,ISupplierRepository suppliers,IWarehouseRepository warehouses,IProductRepository products,IMeasurementUnitRepository units,DocumentNumberService numbers,IUnitOfWork unitOfWork,ICurrentUserService currentUser)
{
 public async Task<int>CreateFromOrderAsync(CreatePurchaseTemplateDto dto){PurchaseTemplate? created=null;await unitOfWork.ExecuteInTransactionAsync(async()=>{var order=await orders.GetByIdAsync(dto.PurchaseOrderId)??throw new InvalidOperationException("Purchase order was not found.");created=new PurchaseTemplate(await numbers.GenerateAsync(DocumentNumberType.PurchaseTemplate,DateTime.Today),dto.Name,order.Id,order.SupplierId,order.WarehouseId,dto.NeededInDays,dto.Priority,currentUser.UserId);foreach(var line in order.Lines)created.AddLine(new PurchaseTemplateLine(line.ProductId,line.MeasurementUnitId,line.OrderedQuantity,line.UnitFactorToBase,order.SupplierId));await templates.AddAsync(created);});return created!.Id;}
 public async Task<int>GenerateRequestAsync(int id){PurchaseRequest? created=null;await unitOfWork.ExecuteInTransactionAsync(async()=>{var template=await templates.GetByIdAsync(id)??throw new InvalidOperationException("Purchase template was not found.");if(await warehouses.GetByIdAsync(template.WarehouseId)is null)throw new InvalidOperationException("Destination warehouse was not found.");if(await suppliers.GetByIdAsync(template.SupplierId)is null)throw new InvalidOperationException("Suggested supplier was not found.");var generation=template.BeginGeneration();var today=DateOnly.FromDateTime(DateTime.Today);created=new PurchaseRequest(await numbers.GenerateAsync(DocumentNumberType.PurchaseRequest,DateTime.Today),template.WarehouseId,today.AddDays(template.NeededInDays),template.Priority,template.Name,null,currentUser.UserId,"PurchaseTemplate",$"{template.Id.ToString(CultureInfo.InvariantCulture)}:{generation.ToString(CultureInfo.InvariantCulture)}");foreach(var line in template.Lines){var product=await products.GetByIdAsync(line.ProductId)??throw new ArgumentException("Product was not found.");if(!product.IsActive||product.ProductType==ProductType.PreparedToOrder)throw new InvalidOperationException("Purchase requests require an active purchasable product.");var unit=await units.GetByIdAsync(line.MeasurementUnitId)??throw new ArgumentException("Measurement unit was not found.");if(!unit.IsActive||!product.MeasurementUnitId.HasValue)throw new InvalidOperationException("Product and requested unit must use managed active units.");var stockUnit=await units.GetByIdAsync(product.MeasurementUnitId.Value)??throw new InvalidOperationException("Product stock unit was not found.");if(stockUnit.Dimension!=unit.Dimension)throw new InvalidOperationException("Requested unit and product stock unit must use the same measurement dimension.");created.AddLine(new PurchaseRequestLine(line.ProductId,line.MeasurementUnitId,line.RequestedQuantity,unit.FactorToBaseUnit/stockUnit.FactorToBaseUnit,line.SuggestedSupplierId,null));}await requests.AddAsync(created);});return created!.Id;}
 public async Task SetActiveAsync(int id,bool active){await unitOfWork.ExecuteInTransactionAsync(async()=>{var value=await templates.GetByIdAsync(id)??throw new InvalidOperationException("Purchase template was not found.");value.SetActive(active);await Task.CompletedTask;});}
 public async Task<List<PurchaseTemplateDto>>GetAllAsync(){var ss=(await suppliers.GetAllAsync()).ToDictionary(x=>x.Id,x=>x.Name);var ws=(await warehouses.GetAllAsync()).ToDictionary(x=>x.Id,x=>x.Name);var ps=(await products.GetAllAsync(null)).ToDictionary(x=>x.Id,x=>$"{x.ProductCode} — {x.Name}");var us=(await units.GetAllAsync()).ToDictionary(x=>x.Id,x=>x.Symbol);return (await templates.GetAllAsync()).Select(x=>new PurchaseTemplateDto{Id=x.Id,TemplateNumber=x.TemplateNumber,Name=x.Name,SupplierName=ss.GetValueOrDefault(x.SupplierId,"-"),WarehouseName=ws.GetValueOrDefault(x.WarehouseId,"-"),NeededInDays=x.NeededInDays,Priority=x.Priority,IsActive=x.IsActive,GenerationCount=x.GenerationCount,Lines=x.Lines.Select(l=>new PurchaseTemplateLineDto{Product=ps.GetValueOrDefault(l.ProductId,"-"),UnitName=us.GetValueOrDefault(l.MeasurementUnitId,"-"),Quantity=l.RequestedQuantity}).ToList()}).ToList();}
}
